package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.behavior.*; import com.wizzadrds.theworldremembers.home.*; import com.wizzadrds.theworldremembers.inventory.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.item.Items; public final class Phase4BehaviorGameTest{@GameTest public void liveVillagerGetsPersistentHomeAndInventory(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);v.getInventory().addItem(new net.minecraft.world.item.ItemStack(Items.BREAD,3));c.runAtTickTime(2,()->{TheWorldRemembers.processWorld(c.getLevel());var home=NpcHomeManager.get(c.getLevel()).get(v.getUUID());var inv=NpcInventoryManager.get(c.getLevel().getServer()).getOrCreate(v.getUUID());var act=NpcActivityManager.get(c.getLevel().getServer()).get(v.getUUID());if(home==null){c.fail("Persistent home missing");return;}if(inv.count("minecraft:bread")!=3){c.fail("Live inventory was not synchronized");return;}if(act==null){c.fail("Activity state missing");return;}c.succeed();});}}